{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLs enabled",
      "resource": "aws_s3_bucket_public_access_block.document_storage",
      "severity": "MEDIUM",
      "explanation": "The resource is missing the 'block_public_acls' argument. While 'ignore_public_acls' is set to true, explicitly setting 'block_public_acls' to true ensures that new public ACLs are rejected at the API level, providing defense-in-depth against accidental or malicious public access grants."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"document_storage\" {\n  bucket = aws_s3_bucket.document_storage.id\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n  block_public_acls       = true\n}",
  "fix_summary": "Added the missing 'block_public_acls = true' attribute to the aws_s3_bucket_public_access_block resource to fully enforce public access blocking settings as recommended by security best practices."
}
